// REST vs GraphQL vs gRPC — side-by-side fetch patterns

// --- REST: multiple round-trips for related data ---
async function getUserWithOrdersREST(userId) {
  const user = await fetch(`/v1/users/${userId}`).then(r => r.json());
  // Under-fetching: need a second call for orders
  const orders = await fetch(`/v1/users/${userId}/orders`).then(r => r.json());
  return { ...user, orders }; // assembled client-side
}

// --- GraphQL: one request, exactly the fields needed ---
async function getUserWithOrdersGQL(userId) {
  const query = `
    query GetUser($id: ID!) {
      user(id: $id) {
        name
        email
        orders { id total status }
      }
    }
  `;
  const res = await fetch('/graphql', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, variables: { id: userId } }),
  });
  const { data } = await res.json();
  return data.user; // one trip, exact shape
}

// --- REST pagination with cursor ---
async function fetchOrdersCursor(after = null) {
  const url = `/v1/orders?limit=20${after ? '&after=' + after : ''}`;
  const { data, next_cursor } = await fetch(url).then(r => r.json());
  return { data, next_cursor }; // stable across concurrent inserts
}

// user.proto — gRPC service definition (Protobuf 3)
syntax = "proto3";

package user;

// The schema is the contract — generated clients are type-safe
service UserService {
  rpc GetUser (GetUserRequest) returns (UserResponse);
  rpc ListOrders (ListOrdersRequest) returns (stream OrderResponse); // server streaming
}

message GetUserRequest {
  int64 id = 1;   // field numbers are stable across versions — never reuse
}

message UserResponse {
  int64  id    = 1;
  string name  = 2;
  string email = 3;
  // Add new optional fields here without breaking old clients
}

message ListOrdersRequest {
  int64 user_id    = 1;
  string page_token = 2; // cursor for pagination
}

message OrderResponse {
  int64  id    = 1;
  double total = 2;
  string status = 3;
}
